/**
 *  A saved connection. One profile can be opened many times; each open produces
 *  a separate live session with its own id.
 */
export type SessionProfile_Deserialize = {
	id?: string,
	name: string,
	kind: SessionKind,
	/**  Tab / tree dot colour, as a CSS colour string. */
	color?: string | null,
	/**
	 *  Session panel group holding this profile; `None` lists it directly
	 *  under its kind's top-level heading.
	 */
	groupId?: string | null,
	/**
	 *  Character encoding of the terminal byte stream, as a WHATWG label
	 *  (`gbk`, `big5`, `shift_jis`, …); absent or unknown means UTF-8.
	 *  Output is decoded in the frontend right before it reaches xterm —
	 *  after the ZMODEM / XMODEM sentries, which need the raw bytes — and
	 *  keyboard input is encoded by `SessionManager::write_text`; the
	 *  binary write path never converts. See `session::encoding`.
	 */
	encoding?: string | null,
	/**
	 *  Locale handed to the shell as `LANG`: put in a local shell's
	 *  environment, requested from an SSH server (which applies it only with
	 *  `AcceptEnv LANG`). Absent means automatic; see `session::locale`.
	 */
	locale?: string | null,
	/**
	 *  What the Backspace key sends: `controlH` for `^H` (0x08), which old
	 *  network gear, serial consoles and some Unix systems take as erase;
	 *  absent means `^?` (0x7f), xterm's own. The key is translated in the
	 *  frontend (`TerminalController.filterKey`); nothing here reads it.
	 */
	backspace?: BackspaceKey | null,
	/**
	 *  Whether every session opened from this profile writes the terminal
	 *  output it receives to a file, one file per connection. Off unless the
	 *  dialog's checkbox was ticked; see `session::recording`.
	 */
	record?: boolean,
	/**
	 *  Folder the recordings are written to; absent means
	 *  `session::recording::default_dir`.
	 */
	recordDir?: string | null,
	shell?: string | null,
	cwd?: string | null,
	host?: string | null,
	port?: number | null,
	username?: string | null,
	auth?: AuthKind | null,
	password?: string | null,
	privateKeyPath?: string | null,
	passphrase?: string | null,
	/**
	 *  Saved SSH / SFTP profile to tunnel through (OpenSSH's `ProxyJump`):
	 *  the transport to that host is opened first and this session's SSH
	 *  handshake runs inside a `direct-tcpip` channel on it, so a host only
	 *  reachable from the jump host's network can be opened directly. The
	 *  jump profile may itself name a jump host, giving a chain; see
	 *  `Store::jump_chain`.
	 */
	jumpProfileId?: string | null,
	/**
	 *  Port forwards saved with this profile, established when a session
	 *  opens. Imported from an OpenSSH config's `LocalForward`,
	 *  `RemoteForward` and `DynamicForward` lines (see `ssh_config`); a
	 *  forward that cannot start is reported and skipped, never fails the
	 *  session, the way `ssh host` treats one.
	 */
	forwards?: PortForwardSpec[],
	portName?: string | null,
	baudRate?: number | null,
	dataBits?: number | null,
	stopBits?: number | null,
	/**  `none` | `odd` | `even` */
	parity?: string | null,
	/**  `none` | `software` | `hardware` */
	flowControl?: string | null,
};

/**
 *  A saved connection. One profile can be opened many times; each open produces
 *  a separate live session with its own id.
 */
