/**
 *  The colour theme of the user interface. It is a front-end setting kept in
 *  the webview's own storage; the backend only remembers the last one so the
 *  next window can be created in its background colour (`store::startup_theme`).
 */
export type Theme = "dark" | "light" |
/**  The two palettes ported from serialX; see `ThemeMode` in `src/types.ts`. */
"serialx-dark" | "serialx-light";

export type TransferItem = {
	local: string,
	remote: string,
	upload: boolean,
	directory?: boolean,
};

export type TransferOptions = {
	requests: number,
	chunkKib: number,
	files: number,
	/**
	 *  Flush every uploaded file on the server's disk (fsync@openssh.com)
	 *  before committing it. Off by default: the flush waits for the
	 *  server's disk on every file and paces small-file batches. Unsupported
	 *  servers reject uploads with this enabled. A flush is separate from
	 *  replacement atomicity: the two-rename fallback has a visibility gap.
	 */
	durable?: boolean,
	/**
	 *  Pack a folder upload into a tar archive and stream it into
	 *  `tar -xf -` on the server, instead of writing every file over SFTP.
	 *  Off by default, and nothing else in the engine looks at it. It covers
	 *  one folder upload into a target directory that is absent or empty,
	 *  needs a remote `tar` and a POSIX shell, and gives up the per-file
	 *  resume, atomic commit, conflict detection and progress the SFTP path
	 *  has — see `tar` for the full boundary list.
	 */
	tar?: boolean,
	/**
	 *  Whole-job rate limit on the network payload a job moves, in bytes
	 *  per second, shared by every wire path it runs (SFTP read/write
	 *  requests, FTP data sockets, the tar pipe, and the remote read-back
	 *  a resume verifies with). Protocol control messages and purely local
	 *  disk work — source signatures, local prefix hashing — are not
	 *  counted; the bytes are charged once, where they cross the wire.
	 *  Zero means unlimited. A slice's tokens are taken exactly when it
	 *  starts moving, short DATA and EOF reads give their unused tokens
	 *  back, and waits never reserve future budget, so pausing or
	 *  cancelling mid-wait leaves no debt behind. The burst is bounded by
	 *  one second of budget (capped at 1 MiB), and low-rate jobs move in
	 *  ~100 ms slices instead of whole chunks.
	 */
	rateLimitBps?: number,
};

export type TransferProgress = {
	transferred: number,
	total: number,
};

export type Workspace = {
	id?: string,
	name?: string,
	server?: ServerRef,
	/**  Absolute directory of the project on the server (the baseline code). */
	root?: string,
	/**  Shell prelude run before commands, e.g. `conda activate vfi`. */
	env?: string,
	commands?: WorkspaceCommand[],
	/**
	 *  Where this project's runs and logs are written. Empty means
	 *  `<root>/.edgeterm/runs`.
	 */
	runRoot?: string,
	baselineExperimentId?: string | null,
	createdAt?: number,
	updatedAt?: number,
};

export type WorkspaceCommand = {
	id?: string,
	label?: string,
	command?: string,
	kind?: WorkspaceCommandKind,
};

export type WorkspaceCommandKind = "train" | "validate" | "infer" | "shell" | "other";

export type WorkspaceData = {
	workspaces?: Workspace[],
	experiments?: Experiment[],
	runs?: RunRecord[],
};

export type WriteOutcome = {
	/**
	 *  The path the file was actually written to. It can differ from the
	 *  request when the parent directory was reached through a symlink.
	 */
	path: string,
	hash: string,
	size: number,
	/**
	 *  A copy of the previous content, kept because the replace could not be
	 *  confirmed. The path exists on the server.
	 */
	backup?: string | null,
	/**  The new content still sitting under a temporary name on the server. */
	temp?: string | null,
	/**
	 *  The replace could not be verified: the bytes may or may not be in
	 *  place. Callers must keep their recovery material.
	 */
	uncertain?: boolean,
	note?: string,
};

/**
 *  Metadata needed to offer a local file through ZMODEM. The file contents
 *  travel through separate bounded chunk commands so large files are never
 *  materialized in one IPC message.
 */
export type ZmodemFileInfo = {
	name: string,
	size: number,
	/**  Unix seconds. */
	modified: number | null,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

